content.css:
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
.bf-ticker {
  --bf-value-color: var(--bf-strong, #1F2A44);
  --bf-label-color: #79839A;
  --bf-rule-color: var(--bf-rule, #E5E7EB);
  --bf-value-size: 14px;
  --bf-label-size: 9px;
  --bf-gap: 48px;
  --bf-label-transform: uppercase;
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  overflow: hidden;
  box-sizing: border-box;
  /* No licence badge on this visual (SUPPRESS_LICENSE_CHROME), so the 24px
     clear-zone the suite reserves for it is given back to the band. */
  padding-bottom: 0;
}
.bf-ticker:focus-visible {
  outline: 2px solid var(--bf-value-color);
  outline-offset: -2px;
}
.bf-ticker__viewport {
  width: 100%;
  overflow: hidden;
}
.bf-ticker__track {
  display: flex;
  width: max-content;
  will-change: transform;
}
.bf-ticker__strip {
  display: flex;
  align-items: center;
  flex: none;
  padding-right: var(--bf-gap);
  gap: var(--bf-gap);
}
.bf-ticker__item {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex: none;
  white-space: nowrap;
}
.bf-ticker__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: none;
  align-self: center;
}
.bf-ticker__arrow {
  flex: none;
  align-self: center;
  font-size: calc(var(--bf-value-size) * 0.72);
  line-height: 1;
}
.bf-ticker__delta {
  flex: none;
  font-size: calc(var(--bf-value-size) * 0.78);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}
.bf-ticker__value {
  color: var(--bf-value-color);
  font-size: var(--bf-value-size);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}
.bf-ticker__label {
  color: var(--bf-label-color);
  font-size: var(--bf-label-size);
  letter-spacing: 0.12em;
  text-transform: var(--bf-label-transform);
  line-height: 1.2;
}
.bf-ticker__sep {
  flex: none;
  align-self: center;
  font-size: var(--bf-label-size);
}
.bf-ticker__sep--rule {
  width: 1px;
  height: calc(var(--bf-value-size) * 1.1);
}
.bf-ticker__empty {
  width: 100%;
  padding: 0 12px;
  color: var(--bf-label-color);
  font-size: 12px;
  text-align: center;
}
/* Visible to screen readers only: the animated strip is aria-hidden. */
.bf-ticker__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
  list-style: none;
}
@keyframes bf-ticker-scroll {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(calc(-1 * var(--bf-shift, 50%)), 0, 0);
  }
}
@media (prefers-reduced-motion: reduce) {
  .bf-ticker__track {
    animation: none !important;
    transform: none !important;
  }
}
/* Power BI's iframe viewport is not the visual viewport, so the suite uses
   width classes set from options.viewport rather than media queries. */
/* The size tokens are set inline from visual.ts (an inline custom property
   beats anything declared here), so the width classes carry only rules that
   TypeScript does not own. */
.bf-ticker.kt-narrow .bf-ticker__sep {
  opacity: 0.6;
}
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  pointer-events: none;
}
/* Landing page — BFusion dark brand ground: navy field, orange accent rail,
   white headline, muted body. Left-aligned rather than centred, so the eye
   starts in the same place as the rest of the suite's marketing surfaces. */
.kt-landing {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  background: var(--bf-band, #1F2A44);
  padding: 28px 34px;
  box-sizing: border-box;
  overflow: auto;
}
.kt-landing-card {
  border: none;
  box-shadow: none;
  border-radius: 10px;
  padding: 26px 30px 26px 26px;
  text-align: left;
  max-width: 620px;
  background: var(--bf-band, #1F2A44);
  border-left: 4px solid #E8612A;
}
.kt-landing-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 22px;
}
.kt-landing-wordmark {
  color: #FFFFFF;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.2em;
  line-height: 1;
}
.kt-landing-title {
  font-size: 30px;
  font-weight: 700;
  color: #FFFFFF;
  line-height: 1.15;
  letter-spacing: -0.015em;
  margin-bottom: 14px;
}
.kt-landing-desc {
  font-size: 17px;
  color: #C3CCDE;
  line-height: 1.55;
}
.kt-landing-desc b {
  color: #FFFFFF;
  font-weight: 700;
}
.kt-landing-sep {
  height: 1px;
  background: rgba(255, 255, 255, 0.14);
  margin: 24px 0 16px;
  width: 100%;
}
.kt-landing-meta {
  font-size: 13px;
  color: #8A98B4;
  line-height: 1.7;
}
/* Narrow visuals: the band can be short, so give the type room to shrink
   rather than clipping the card. */
.kt-landing.kt-landing--tight {
  padding: 16px 18px;
}
.kt-landing.kt-landing--tight .kt-landing-logo {
  margin-bottom: 14px;
  gap: 9px;
}
.kt-landing.kt-landing--tight .kt-landing-logo svg {
  width: 34px;
  height: 22px;
}
.kt-landing.kt-landing--tight .kt-landing-wordmark {
  font-size: 17px;
}
.kt-landing.kt-landing--tight .kt-landing-title {
  font-size: 21px;
  margin-bottom: 10px;
}
.kt-landing.kt-landing--tight .kt-landing-desc {
  font-size: 14px;
}
.kt-landing.kt-landing--tight .kt-landing-sep {
  margin: 16px 0 10px;
}
.kt-landing.kt-landing--tight .kt-landing-meta {
  font-size: 12px;
}
